  `status` enum('queued','held','done','removed','unprocessed') NOT NULL DEFAULT 'queued',
  `held_by` int(11) DEFAULT NULL,
  `station_id` int(11) DEFAULT NULL,
  `service_id` int(11) DEFAULT NULL,
  `reason` varchar(160) DEFAULT NULL,
  `patient_name` varchar(120) DEFAULT NULL,
  `patient_age` varchar(12) DEFAULT NULL,
  `patient_gender` varchar(10) DEFAULT NULL,
  `patient_address` varchar(255) DEFAULT NULL,
  `vital_temp` varchar(10) DEFAULT NULL,
  `vital_o2sat` varchar(10) DEFAULT NULL,
  `vital_hr` varchar(10) DEFAULT NULL,
  `vital_rr` varchar(10) DEFAULT NULL,
  `vital_weight` varchar(10) DEFAULT NULL,
  `vital_height` varchar(10) DEFAULT NULL,
  `vital_bp` varchar(12) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `stage_since` timestamp NULL DEFAULT NULL,
  `done_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_day_cat_seq` (`day`,`category_id`,`seq`),
  KEY `idx_day_stage_status` (`day`,`stage_id`,`status`),
  KEY `idx_stage_since` (`day`,`stage_id`,`status`,`stage_since`),
  KEY `idx_stage_service` (`stage_id`,`service_id`),
  KEY `idx_station` (`station_id`),
  KEY `idx_held_by` (`held_by`),
  KEY `idx_patient_name` (`patient_name`),
  KEY `category_id` (`category_id`),
  KEY `service_id` (`service_id`),
  CONSTRAINT `hqTicket_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `hqCategory` (`id`),
  CONSTRAINT `hqTicket_ibfk_2` FOREIGN KEY (`stage_id`) REFERENCES `hqStage` (`id`) ON DELETE SET NULL,
  CONSTRAINT `hqTicket_ibfk_3` FOREIGN KEY (`service_id`) REFERENCES `hqService` (`id`) ON DELETE SET NULL,
  CONSTRAINT `hqTicket_ibfk_4` FOREIGN KEY (`station_id`) REFERENCES `hqStation` (`id`) ON DELETE SET NULL,
  CONSTRAINT `hqTicket_ibfk_5` FOREIGN KEY (`held_by`) REFERENCES `hqUser` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `hqUser`;

CREATE TABLE `hqUser` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `display_name` varchar(60) DEFAULT NULL,
  `is_admin` tinyint(1) NOT NULL DEFAULT 0,
  `archived` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `hqUserStage`;

CREATE TABLE `hqUserStage` (
  `user_id` int(11) NOT NULL,
  `stage_id` int(11) NOT NULL,
  PRIMARY KEY (`user_id`,`stage_id`),
  KEY `idx_stage` (`stage_id`),
  CONSTRAINT `hqUserStage_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `hqUser` (`id`) ON DELETE CASCADE,
  CONSTRAINT `hqUserStage_ibfk_2` FOREIGN KEY (`stage_id`) REFERENCES `hqStage` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `office_designation`;

CREATE TABLE `office_designation` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `officedesignation` varchar(200) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'active',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;




DROP TABLE IF EXISTS `pass`;

CREATE TABLE `pass` (
  `id` int(100) NOT NULL AUTO_INCREMENT,
  `date_requested` datetime NOT NULL,
  `grade_and_section` varchar(50) NOT NULL,
  `name_of_students` text NOT NULL,
  `subject_area` varchar(50) NOT NULL,
  `subject_teacher` varchar(255) DEFAULT NULL,
  `adult_supervisor` varchar(255) DEFAULT NULL,
  `venue` varchar(255) DEFAULT NULL,
  `destination` varchar(255) DEFAULT NULL,
  `signature_type` varchar(50) DEFAULT NULL,
  `parent_consent_type` enum('with_permission','in_company') DEFAULT NULL,
  `parent_consent_through` varchar(255) DEFAULT NULL,
  `parent_consent_proof` varchar(500) DEFAULT NULL,
  `gadget_type` varchar(255) DEFAULT NULL,
  `teacher_email` varchar(255) DEFAULT NULL,
  `date` date NOT NULL,
  `time_from` time NOT NULL,
  `time_to` time NOT NULL,
  `purposes` text NOT NULL,
  `adviser_email` text NOT NULL,
  `is_approved` enum('Approved','Pending','Disapproved','') NOT NULL,
  `denial_reason` text DEFAULT NULL,
  `requestorLRN` varchar(100) NOT NULL,
  `sy` varchar(20) NOT NULL,
  `adviser_approved` enum('Pending','Approved','Disapproved') DEFAULT 'Pending',
  `supervisor_approved` enum('Pending','Approved','Disapproved') NOT NULL DEFAULT 'Pending',
  `cid_approved` enum('Pending','Approved','Disapproved') DEFAULT 'Pending',
  `adviser_approved_at` datetime DEFAULT NULL,
  `cid_approved_at` datetime DEFAULT NULL,
  `requires_adviser_approval` tinyint(1) DEFAULT 0,
  `approval_workflow` enum('direct_cid','adviser_cid','food_ssd') DEFAULT 'direct_cid',
  `id_number` varchar(50) DEFAULT NULL,
  `mobile_number` int(50) DEFAULT NULL,
  `endorsed_by` varchar(255) DEFAULT NULL,
  `ssd_approved` enum('Pending','Approved','Disapproved') DEFAULT 'Pending',
  `ssd_approved_at` datetime DEFAULT NULL,
  `food_committee_approved` enum('Pending','Approved','Disapproved','Partially Approved') DEFAULT 'Pending',
  `food_committee_approved_at` datetime DEFAULT NULL,
  `cid_approved_by` int(11) DEFAULT NULL,
  `adviser_approved_by` int(11) DEFAULT NULL,
  `food_committee_approved_by` int(11) DEFAULT NULL,
  `ssd_approved_by` int(11) DEFAULT NULL,
  `supervisor_approved_at` datetime DEFAULT NULL,
  `supervisor_approved_by` int(11) DEFAULT NULL,
  `officer_in_charge_approved` varchar(20) DEFAULT NULL,
  `officer_in_charge_approved_at` datetime DEFAULT NULL,
  `officer_in_charge_approved_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS `pass_request`;

CREATE TABLE `pass_request` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `studentID` varchar(50) DEFAULT NULL,
  `passType` varchar(50) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `statusDate` date DEFAULT NULL,
  `dateOfSubmission` date DEFAULT NULL,
  `passReferenceID` int(11) NOT NULL,
  `is_notification_read` tinyint(1) DEFAULT 0,
  `sy` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `studentID` (`studentID`),
  KEY `passType` (`passType`),
  KEY `fk_passReferenceID` (`passReferenceID`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS `passes`;

CREATE TABLE `passes` (
  `passType` varchar(100) NOT NULL,
  `status` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`passType`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS `schema_migrations`;

CREATE TABLE `schema_migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `applied_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_schema_migrations_migration` (`migration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `scilab_availability`;

CREATE TABLE `scilab_availability` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
